52	// USD formatter — this wizard's 2-decimal style ("$5.00"). Used verbatim for the
53	// USD display path (byte-for-byte unchanged) and for the "billed in USD" note.
54	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
55	const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
