162	/** Same hostname rule as the server (lib/game-order.ts) + VPS deploy. */
163	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
164	type Values = Record<string, string | number | boolean>;
165	
166	/** sessionStorage key for the in-progress order — survives the Stripe round-trip. */
167	const DRAFT_KEY = "nxeon.gamedeploy.draft.v1";
