169	/** Compact stepper, matching the VPS DeployWizard. */
170	function Stepper({ step, steps }: { step: number; steps: string[] }) {
171	  return (
172	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
173	      {steps.map((s, i) => (
174	        <div key={s} className="flex items-center gap-2">
175	          <span
176	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
177	              i === step
178	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
179	                : i < step
180	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
181	                  : "border-white/10 text-slate-500"
182	            }`}
183	          >
184	            {i < step ? "✓" : i + 1}
185	          </span>
186	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
187	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
188	        </div>
189	      ))}
190	    </div>
191	  );
192	}
193	
194	/** Build the default gameplay values for a family schema. */
195	function defaultValues(schema: FamilySchema | null): Values {
196	  const out: Values = {};
197	  if (!schema) return out;
198	  for (const f of schema.fields) out[f.key] = f.default;
199	  return out;
200	}
