202	/**
203	 * A proper multi-step game-server deploy wizard — the game analogue of the VPS
204	 * DeployWizard. Steps: Game → Plan & term → Server settings → Review & checkout.
205	 *
206	 * TRUTH BY CONSTRUCTION: every price is derived from the tier's real DB price
207	 * (`priceCents`) run through `termPriceCents` with the SAME live `annualDiscountPct`
208	 * the server charges and renews at, and the wallet/card split is the same
209	 * `walletSplit` math the action charges. So what the customer sees === what
210	 * `payAndDeployGame` charges. Game bills FULL from month 1 — no first-month-free.
211	 */
212	export function GameDeployWizard({
213	  games,
214	  tiers,
215	  balanceCents,
216	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
217	  schemas,
218	  stripeConfigured,
219	  email,
220	  dedicatedIpAvailable = false,
221	  dedicatedIpPriceCents = 0,
222	  customPlanFloor, customPlanCeiling, customPlanRates,
223	}: {
224	  games: GameMeta[];
225	  tiers: Tier[];
226	  balanceCents: number;
227	  annualDiscountPct?: number;
228	  /** family → per-game customization schema (only families that have one). */
229	  schemas: Record<string, FamilySchema>;
230	  /** Whether card checkout is available (else wallet-only). */
231	  stripeConfigured: boolean;
232	  /** The account's email — PaymentStep's receipt/invoice-email display. */
233	  email: string;
234	  /** Whether the dedicated-IP pool has free IPs to offer. */
235	  dedicatedIpAvailable?: boolean;
236	  /** Admin-configured monthly price for a dedicated IP (cents). */
237	  dedicatedIpPriceCents?: number;
238	  /** "Build a custom server" — same floor/ceiling/rates resolved server-side for
239	   *  the VPS wizard (lib/custom-plan.ts), shared here so a game customer past the
240	   *  top of a family's tier ladder gets identical guardrails/pricing. See
241	   *  components/customer/DeployWizard.tsx's matching props for the full doc. */
242	  customPlanFloor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number; bandwidthTB: number };
243	  customPlanCeiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
244	  customPlanRates?: { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };
245	}) {
246	  const [state, action, pending] = useActionState(
247	    payAndDeployGame,
248	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
249	  );
250	  // The embedded Stripe session to feed PaymentStep (was: a StripeCheckoutModal).
251	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
252	  // Tracks the Payment step's OWN session request — mirrors DeployWizard's
253	  // stripePhase/checkoutSession split.
254	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
255	
256	  // Only accept a session as the result of an EXPLICIT submit (armed in
257	  // requestStripeSession/the Deploy button), so a stale session can never
258	  // apply on its own (e.g. after a back-button remount).
259	  const submittedRef = useRef(false);
260	  useEffect(() => {
261	    if (submittedRef.current) {
262	      submittedRef.current = false;
263	      if (state?.checkout) {
264	        // The "game" conversion is fired at FULFILMENT (PurchaseTracker, with the real
265	        // charged value + transaction_id) — NOT here at checkout-start, which would
266	        // count customers who abandon at the payment step.
267	        setCheckoutSession(state.checkout);
268	      } else {
269	        setCheckoutSession(null);
270	        if (state?.error) setStripePhase("error");
271	      }
272	    }
273	  }, [state]);
274	  // PaymentStep asks for a session the SAME way the old "Deploy" button did — a
275	  // real requestSubmit() through the exact same <form action={action}>.
276	  const formRef = useRef<HTMLFormElement>(null);
277	  const requestStripeSession = useCallback(() => {
278	    setStripePhase("loading");
279	    submittedRef.current = true;
280	    formRef.current?.requestSubmit();
281	  }, []);
282	  // PaymentStep's PayPal/Coinbase support isn't wired for game servers yet —
283	  // these stubs are never invoked since `paypal`/`coinbaseReady` are both off.
284	  const gamePaymentUnavailable = useCallback(async () => ({ error: "That payment method isn't available for game servers yet." }), []);
285	
286	  const steps = ["Game", "Plan", "Settings", "Review"];
287	  const [step, setStep] = useState(0);
288	
289	  // Deploy-funnel instrumentation (see DeployWizard for the rationale).
290	  useEffect(() => {
291	    trackDeployStep("game", steps[step] ?? String(step), step);
292	    // eslint-disable-next-line react-hooks/exhaustive-deps
293	  }, [step]);
294	  useEffect(() => {
295	    if (state?.error) trackDeployError("game", steps[step] ?? "Review", step, "ORDER_ERROR", state.error);
296	    // eslint-disable-next-line react-hooks/exhaustive-deps
297	  }, [state?.error]);
298	
299	  // DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
300	  // selected display currency converts the USD-cents amount for on-screen reference
301	  // only. Everything posted to payAndDeployGame stays USD cents (hidden fields carry
302	  // selections, not money).
303	  const { currency, rate } = useCurrency();
304	  const money = (c: number) =>
305	    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
306	
307	  const firstGame = games[0]?.family ?? "";
308	  const [game, setGame] = useState(firstGame);
309	  const [selected, setSelected] = useState<string | null>(null);
310	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
311	  const [serverName, setServerName] = useState("");
312	  const [hostname, setHostname] = useState("");
313	  // `game` above defaults straight to `firstGame` rather than going through
314	  // `pickGame()` (the function that ALSO seeds variant/values) — so these two
315	  // need the SAME lazy-initializer logic, or a customer who never re-clicks
316	  // the pre-selected game (the common case — Minecraft is `firstGame`) ships
317	  // through Settings/Review with `values` stuck at `{}` the whole time. That
318	  // produced a real, reported bug: the Review step's "Configuration" line
319	  // read every field as changed-from-default and printed literal "undefined"
320	  // for each one, because `values[f.key]` really was undefined — schema
321	  // defaults were never actually applied to state, only ever displayed via
322	  // the Settings step's `value ?? field.default` fallback.
323	  const [variant, setVariant] = useState(schemas[firstGame]?.defaultVariant ?? "");
324	  // Minecraft only — `<subdomain>.play.nxeon.cloud`, how players actually
325	  // connect (see lib/game-subdomain.ts). Required at checkout for this family.
326	  const [subdomain, setSubdomain] = useState("");
327	  const [values, setValues] = useState<Values>(defaultValues(schemas[firstGame] ?? null));
328	  const [dedicatedIp, setDedicatedIp] = useState(false);
329	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
330	  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
331	  // Clicking "Change" next to the billing term inside PaymentStep's Order
332	  // Summary reveals the same TermLadder cards inline instead of navigating
333	  // away from the last step — mirrors DeployWizard's showTermPicker pattern.
334	  const [showTermPicker, setShowTermPicker] = useState(false);
335	
336	  // Game-picker (Step 1) controls — presentation-only, never posted to the action.
337	  const [gameQuery, setGameQuery] = useState("");
338	  const [gameCategory, setGameCategory] = useState("All");
339	  const [gameSort, setGameSort] = useState<"featured" | "name" | "price">("featured");
340	
341	  // "Build a custom server" — a confirmed custom GamePlan tier (real Plan +
342	  // GamePlan rows, both created inactive; see lib/custom-plan.ts
343	  // createCustomGamePlan) is never in the server-fetched `tiers` prop, so it's
344	  // merged in here exactly like DeployWizard merges its own `customPlan`.
345	  const [customTier, setCustomTier] = useState<Tier | null>(null);
346	  const [customBuilderOpen, setCustomBuilderOpen] = useState(false);
347	  const [customSpec, setCustomSpec] = useState<CustomPlanSpec | null>(null);
348	  const [customPlayers, setCustomPlayers] = useState<number | null>(null);
349	  const [customCapacity, setCustomCapacity] = useState<{ ok: boolean; reason?: string } | null>(null);
350	  const [customChecking, setCustomChecking] = useState(false);
351	  const [customConfirming, setCustomConfirming] = useState(false);
352	  const [customError, setCustomError] = useState("");
353	
354	  const gameTiers = useMemo(() => {
355	    const base = tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents);
356	    return customTier && customTier.gameFamily === game ? [...base, customTier] : base;
357	  }, [tiers, game, customTier]);
358	  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
359	  const schema = schemas[game] ?? null;
360	
361	  /**
362	   * Custom-server builder for game orders — mirrors DeployWizard's, plus a
363	   * "how many players?" convenience slider (lib/game-player-recommend.ts) that
364	   * DEFAULT-SETS the same underlying cpu/ram/disk sliders; the customer can still
365	   * freely override above or below whatever it suggests.
366	   */
367	  const openCustomBuilder = () => {
368	    if (!customPlanFloor) return;
369	    setCustomSpec((cur) => cur ?? { cpuCores: customPlanFloor.cpuCores, ramMB: customPlanFloor.ramMB, diskGB: customPlanFloor.diskGB });
370	    setCustomError("");
371	    setCustomBuilderOpen(true);
372	  };
373	  const applyPlayerRecommendation = (players: number) => {
374	    setCustomPlayers(players);
375	    if (!customPlanFloor || !customPlanCeiling) return;
376	    const rec = recommendedSpecForPlayers(game as GameFamily, players);
377	    setCustomSpec(clampCustomPlanSpec(rec, customPlanFloor, customPlanCeiling));
378	  };
379	  const customPreviewPrice =
380	    customSpec && customPlanFloor && customPlanRates
381	      ? computeCustomPlanPriceCents(customSpec, customPlanFloor, customPlanRates)
382	      : 0;
383	  const customSpecValid =
384	    customSpec && customPlanFloor && customPlanCeiling
385	      ? validateCustomPlanSpec(customSpec, customPlanFloor, customPlanCeiling)
386	      : null;
387	  useEffect(() => {
388	    if (!customBuilderOpen || !customSpec || !customSpecValid?.ok) {
389	      setCustomCapacity(null);
390	      return;
391	    }
392	    let cancelled = false;
393	    setCustomChecking(true);
394	    const t = setTimeout(async () => {
395	      try {
396	        const res = await quoteCustomPlanAction(customSpec);
397	        if (cancelled) return;
398	        if (!res.ok) setCustomCapacity({ ok: false, reason: res.error });
399	        else setCustomCapacity({ ok: !!res.capacityOk, reason: res.capacityReason });
400	      } catch {
401	        if (!cancelled) setCustomCapacity({ ok: false, reason: "Couldn't check capacity — try again." });
402	      } finally {
403	        if (!cancelled) setCustomChecking(false);
404	      }
405	    }, 450);
406	    return () => {
407	      cancelled = true;
408	      clearTimeout(t);
409	    };
410	    // eslint-disable-next-line react-hooks/exhaustive-deps
411	  }, [customBuilderOpen, customSpec?.cpuCores, customSpec?.ramMB, customSpec?.diskGB]);
412	
413	  async function confirmCustomBuilder() {
414	    if (!customSpec) return;
415	    setCustomError("");
416	    setCustomConfirming(true);
417	    try {
418	      const res = await confirmCustomGamePlanAction({
419	        cpuCores: customSpec.cpuCores,
420	        ramMB: customSpec.ramMB,
421	        diskGB: customSpec.diskGB,
422	        gameFamily: game,
423	        players: customPlayers ?? undefined,
424	      });
425	      if (!res.ok || !res.tier) {
426	        setCustomError(res.error ?? "Couldn't set up that custom server.");
427	        return;
428	      }
429	      const t = res.tier;
430	      const newTier: Tier = {
431	        id: t.gamePlanId,
432	        gameFamily: game,
433	        name: t.name,
434	        ramMB: t.ramMB,
435	        cpuCores: t.cpuCores,
436	        diskGB: t.diskGB,
437	        slots: t.slots,
438	        priceCents: t.priceCents,
439	        termMonths: t.termMonths,
440	        featured: false,
441	      };
442	      setCustomTier(newTier);
443	      setSelected(newTier.id);
444	      setCustomBuilderOpen(false);
445	    } finally {
446	      setCustomConfirming(false);
447	    }
448	  }
449	
450	  // Cheapest monthly price per family — powers the "from $X/mo" badge + price sort.

450	  // Cheapest monthly price per family — powers the "from $X/mo" badge + price sort.
451	  const fromMonthlyByFamily = useMemo(() => {
452	    const m: Record<string, number> = {};
453	    for (const t of tiers) {
454	      const mo = Math.round(t.priceCents / Math.max(1, t.termMonths));
455	      if (m[t.gameFamily] === undefined || mo < m[t.gameFamily]) m[t.gameFamily] = mo;
456	    }
457	    return m;
458	  }, [tiers]);
459	  const featuredFamilies = useMemo(
460	    () => new Set(tiers.filter((t) => t.featured).map((t) => t.gameFamily)),
461	    [tiers],
462	  );
463	  const tierCountByFamily = useMemo(() => {
464	    const m: Record<string, number> = {};
465	    for (const t of tiers) m[t.gameFamily] = (m[t.gameFamily] ?? 0) + 1;
466	    return m;
467	  }, [tiers]);
468	  // Only surface category pills for genres that actually have games available.
469	  const gameCategories = useMemo(() => {
470	    const set = new Set<string>();
471	    for (const g of games) set.add(GAME_GENRE[g.family] ?? "Other");
472	    return ["All", ...[...set].sort()];
473	  }, [games]);
474	  const visibleGames = useMemo(() => {
475	    const q = gameQuery.trim().toLowerCase();
476	    const list = games.filter((g) => {
477	      if (gameCategory !== "All" && (GAME_GENRE[g.family] ?? "Other") !== gameCategory) return false;
478	      if (q && !g.name.toLowerCase().includes(q) && !g.family.includes(q)) return false;
479	      return true;
480	    });
481	    const sorted = [...list];
482	    if (gameSort === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
483	    else if (gameSort === "price")
