7	/**
8	 * GameCoverTile — a compact portrait "box-art" cover, the small-scale version of
9	 * the /game-servers hero carousel cover, for use in pickers (e.g. the game deploy
10	 * wizard). Resolution chain (first that loads wins):
11	 *
12	 *   public/games/art/<artSlug>_poster.jpg                ← real portrait key-art
13	 *   public/logos/games/covers/<family>.{webp,jpg,png}    ← owner cover drop-in
14	 *   public/logos/games/<family>.png                      ← wordmark fallback
15	 *   per-game gradient                                     ← final fallback
16	 *
17	 * Plain <img> so the onError chain advances client-side. Aspect ~2:3 (poster).
18	 */
19	export function GameCoverTile({ family, name }: { family: string; name: string }) {
20	  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", from: "#334155", to: "#64748b" };
21	  const artSlug = GAME_ART_SLUG[family as GameFamily]?.poster;
22	  const chain = [
23	    ...(artSlug ? [`/games/art/${artSlug}_poster.jpg`] : []),
24	    `/logos/games/covers/${family}.webp`,
25	    `/logos/games/covers/${family}.jpg`,
26	    `/logos/games/covers/${family}.png`,
27	    `/logos/games/${family}.png`, // wordmark fallback (not full art)
28	  ];
29	  const [idx, setIdx] = useState(0);
30	  const exhausted = idx >= chain.length;
31	  const isWordmark = idx === chain.length - 1;
32	
33	  return (
34	    <div
35	      className="relative aspect-[2/3] w-full overflow-hidden rounded-lg"
36	      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
37	    >
38	      {!exhausted && (
39	        // eslint-disable-next-line @next/next/no-img-element
40	        <img
41	          src={chain[idx]}
42	          alt={name}
43	          className={isWordmark ? "absolute inset-0 m-auto h-1/2 w-auto object-contain drop-shadow" : "absolute inset-0 h-full w-full object-cover"}
44	          onError={() => setIdx((i) => i + 1)}
45	        />
46	      )}
47	      {exhausted && (
48	        <span className="absolute inset-0 flex items-center justify-center text-2xl" aria-hidden>
49	          {visual.glyph}
50	        </span>
51	      )}
52	      {/* bottom vignette so a name overlaid by the parent stays legible on any art */}
53	      <div className="pointer-events-none absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-black/70 to-transparent" />
54	    </div>
55	  );
56	}
